export const authGetCsrfCookie = <ThrowOnError extends boolean = true>(options?: Options<AuthGetCsrfCookieData, ThrowOnError>): RequestResult<AuthGetCsrfCookieResponses, unknown, ThrowOnError> => (options?.client ?? client).get<AuthGetCsrfCookieResponses, unknown, ThrowOnError>({ url: '/sanctum/csrf-cookie', ...options });
